def parse_csv(text: str, delimiter: str = ",") -> list[list[str]]:
    if not text:
        return []

    results = []
    current_row = []
    current_field = ""
    in_quotes = False
    i = 0
    n = len(text)

    while i < n:
        char = text[i]

        if in_quotes:
            if char == '"':
                # Çift tırnak (escaped quote) kontrolü: "" -> "
                if i + 1 < n and text[i+1] == '"':
                    current_field += '"'
                    i += 2
                    continue
                else:
                    # Tırnak kapandı
                    in_quotes = False
                    # Kural: Kapanan tırnaktan hemen sonra ayırıcı veya satır sonu gelmeli
                    if i + 1 < n and text[i+1] not in (delimiter, "\n", "\r"):
                        raise ValueError("Hatalı girdi: Tırnak sonrası geçersiz karakter.")
            else:
                current_field += char
        else:
            if char == '"':
                # Alan tırnakla başlıyorsa
                if current_field != "":
                    # Kural: "Tırnaksız alanların ortasındaki \" sıradan karakterdir." 
                    # Bu kurala göre, eğer bir alan daha önce tırnak ile başlamadıysa, 
                    # içindeki her şey (tırnak dahil) normal karakterdir.
                    current_field += char
                else:
                    in_quotes = True
            elif char == delimiter:
                current_row.append(current_field)
                current_field = ""
            elif char == "\n" or char == "\r":
                # Satır sonu işleme
                current_row.append(current_field)
                results.append(current_row)
                current_row = []
                current_field = ""
                if char == "\r" and i + 1 < n and text[i+1] == "\n":
                    i += 1
            else:
                current_field += char
        i += 1

    if in_quotes:
        raise ValueError("Hatalı girdi: Kapanmayan tırnak.")

    # Metnin sonundaki tek satır sonu yeni bir kayıt oluşturmaz.
    # Eğer metin bir satır sonu ile bitmiyorsa, kalan veriyi ekle.
    if n > 0 and text[-1] not in ("\n", "\r"):
        current_row.append(current_field)
        results.append(current_row)
    elif n > 0 and text[-1] in ("\n", "\r") and current_row:
        # Eğer döngü bir satır sonu ile bittiyse, zaten append yapıldı.
        pass
    elif n > 0 and text[-1] in ("\n", "\r") and not results:
        # Sadece tek bir boş satır varsa (örn: "\n"), kural gereği [""] dönmeli mi?
        # "Ortadaki boş bir satır tek boş alanlı kayıttır: ['']" 
        # Eğer metin sadece "\n" ise, bu aslında bir kayıt ve o da boş.
        results.append([""])

    return results

def test_parse_csv():
    test_cases = [
        ("", []),
        ('a,"b,c",d', [['a', 'b,c', 'd']]),
        ('a,"b""c",d', [['a', 'b"c', 'd']]),
        ('a,"b\nc",d', [['a', 'b\nc', 'd']]),
        ('a,\n,b', [['a', '', ''], ['', 'b']]), 
        ('a,b\n', [['a', 'b']]),
        ('a,b', [['a', 'b']]),
        ('"quoted","with ""quotes"""', [['quoted', 'with "quotes"']]),
        ('normal,"unclosed quote', ValueError), # Kapanmayan tırnak hatası
        ('"error"c,d', ValueError),             # Tırnaktan sonra geçersiz karakter
    ]

    for text, expected in test_cases:
        try:
            result = parse_csv(text)
            if isinstance(expected, type) and issubclass(expected, Exception):
                raise AssertionError(f"Expected {expected.__name__} for {repr(text)}")
            assert result == expected, f"Failed on {repr(text)}: expected {expected}, got {result}"
        except ValueError as e:
            if not isinstance(expected, type) or not issubclass(expected, Exception):
                raise AssertionError(f"Unexpected ValueError for {repr(text)}: {e}")
        except Exception as e:
            raise AssertionError(f"Error on {repr(text)}: {e}")

    print("Tüm testler başarıyla geçti!")

if __name__ == "__main__":
    test_parse_csv()

